return {["scripts/items/healing_harness.lua"]={["Path"]="scripts/items/healing_harness.lua",["SHA256"]="0331198459102893a3f504285adb2482861869383d4c212bf4830361dbf7fb3e",["Text"]="-----------------------------------\n-- ID: 14495\n-- Item: Healing Harness\n-- Item Effect: Restores 50-75 HP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getHP() == target:getMaxHP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local hpHeal = math.randomInt(50, 75)\n    local dif = target:getMaxHP() - target:getHP()\n    if hpHeal > dif then\n        hpHeal = dif\n    end\n\n    target:addHP(hpHeal)\n    target:messageBasic(xi.msg.basic.RECOVERS_HP, 0, hpHeal)\nend\n\nreturn itemObject\n"},["scripts/items/healing_justaucorps.lua"]={["Path"]="scripts/items/healing_justaucorps.lua",["SHA256"]="64253906e47844ae8b2db41a570ed1b78f09f8a62b594d3c497f40b4e100c3de",["Text"]="-----------------------------------\n-- ID: 14496\n-- Item: Healing Justaucorps\n-- Item Effect: Restores 150-175 HP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getHP() == target:getMaxHP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local hpHeal = math.randomInt(150, 175)\n    local dif = target:getMaxHP() - target:getHP()\n    if hpHeal > dif then\n        hpHeal = dif\n    end\n\n    target:addHP(hpHeal)\n    target:messageBasic(xi.msg.basic.RECOVERS_HP, 0, hpHeal)\nend\n\nreturn itemObject\n"},["scripts/items/healing_vest.lua"]={["Path"]="scripts/items/healing_vest.lua",["SHA256"]="4d24987975da83b7269ad271d988c740df3b6af248b089dce7f5d3faf395586b",["Text"]="-----------------------------------\n-- ID: 14493\n-- Item: Healing Vest\n-- Item Effect: Restores 90-105 HP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getHP() == target:getMaxHP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local hpHeal = math.randomInt(90, 105)\n    local dif = target:getMaxHP() - target:getHP()\n    if hpHeal > dif then\n        hpHeal = dif\n    end\n\n    target:addHP(hpHeal)\n    target:messageBasic(xi.msg.basic.RECOVERS_HP, 0, hpHeal)\nend\n\nreturn itemObject\n"},["scripts/items/heart_chocolate.lua"]={["Path"]="scripts/items/heart_chocolate.lua",["SHA256"]="d39e9b21a063eb14327bc2d524102e0207d96fa65a7846927d39ed2be73fe6b3",["Text"]="-----------------------------------\n-- ID: 4497\n-- Item: heart_chocolate\n-- Food Effect: 60Min, All Races\n-- Magic Regen While Healing 4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.MPHEAL, 4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/heat_rod.lua"]={["Path"]="scripts/items/heat_rod.lua",["SHA256"]="4d50cdc980afd9f42cd42f0ee1ae6ef0690f586ef2af4dfbb5511a51af010b7d",["Text"]="-----------------------------------\n-- ID: 17071\n-- Item: Heat Rod\n-- Additional effect: lightning damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat  = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    local pTable =\n    {\n        chance         = utils.clamp(dStat * 0.463, 0, 25), -- 0-25% over 54 dINT, approx.\n        basePower      = math.randomInt(6, 8),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.THUNDER,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/heavy_metal_pouch.lua"]={["Path"]="scripts/items/heavy_metal_pouch.lua",["SHA256"]="57c68174e40bcb7f289f3dec5106fadbc8a6525e7ee871afe83359fd5ce5c056",["Text"]="-----------------------------------\n-- ID: 5910\n-- Heavy Metal Pouch\n-- Breaks up a Heavy Metal Pouch\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.PLATE_OF_HEAVY_METAL, math.randomInt(3, 19) } })\nend\n\nreturn itemObject\n"},["scripts/items/hedgehog_pie.lua"]={["Path"]="scripts/items/hedgehog_pie.lua",["SHA256"]="9a8ca6d888f7799deb648707ea84d272647a3db69c63c9c626ed0056268f0b08",["Text"]="-----------------------------------\n-- ID: 5146\n-- Item: hedgehog_pie\n-- Food Effect: 180Min, All Races\n-----------------------------------\n-- Health 55\n-- Strength 6\n-- Vitality 2\n-- Intelligence -3\n-- Mind 3\n-- Magic Regen While Healing 2\n-- Health Regen While Healing 2\n-- Attack % 18\n-- Attack Cap 90\n-- Accuracy 5\n-- Ranged ATT % 18\n-- Ranged ATT Cap 90\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 55)\n    effect:addMod(xi.mod.STR, 6)\n    effect:addMod(xi.mod.VIT, 2)\n    effect:addMod(xi.mod.INT, -3)\n    effect:addMod(xi.mod.MND, 3)\n    effect:addMod(xi.mod.HPHEAL, 2)\n    effect:addMod(xi.mod.MPHEAL, 2)\n    effect:addMod(xi.mod.FOOD_ATTP, 18)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 90)\n    effect:addMod(xi.mod.ACC, 5)\n    effect:addMod(xi.mod.FOOD_RATTP, 18)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 90)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/hellfire_axe.lua"]={["Path"]="scripts/items/hellfire_axe.lua",["SHA256"]="e429c7d47fa12e5adaeae99f5c3eb4c069315508a51e14b49b4f84f1e16dca1c",["Text"]="-----------------------------------\n-- ID: 16713\n-- Item: Hellfire Axe\n-- Additional effect: fire damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 5,\n        basePower      = math.randomInt(3, 5),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.FIRE,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/hellfire_sword.lua"]={["Path"]="scripts/items/hellfire_sword.lua",["SHA256"]="ec3edffdfe541d4d1e4594c4fef14ef3ee419b7ab50eefb2ab8dbb0d46ad2595",["Text"]="-----------------------------------\n-- ID: 16928\n-- Item: Hellfire Sword\n-- Additional effect: fire damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 5,\n        basePower      = math.randomInt(3, 5),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.FIRE,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/hellsteak.lua"]={["Path"]="scripts/items/hellsteak.lua",["SHA256"]="93523e3917e5a6486a9c1743b75fe26cf21009040bf696b6ebb4f03c2d66e771",["Text"]="-----------------------------------\n-- ID: 5609\n-- Item: hellsteak\n-- Food Effect: 180Min, All Races\n-----------------------------------\n-- Health 20\n-- Strength 6\n-- Intelligence -2\n-- Health Regen While Healing 2\n-- hMP +1\n-- Attack % 18 (cap 145)\n-- Ranged ATT % 18 (cap 145)\n-- Dragon Killer 5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 20)\n    effect:addMod(xi.mod.STR, 6)\n    effect:addMod(xi.mod.INT, -2)\n    effect:addMod(xi.mod.HPHEAL, 2)\n    effect:addMod(xi.mod.MPHEAL, 1)\n    effect:addMod(xi.mod.FOOD_ATTP, 18)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 145)\n    effect:addMod(xi.mod.FOOD_RATTP, 18)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 145)\n    effect:addMod(xi.mod.DRAGON_KILLER, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/hellsteak_+1.lua"]={["Path"]="scripts/items/hellsteak_+1.lua",["SHA256"]="3257abe4d6a87a80497d4cfc76bfad3db63e78ef412c843f24748571e40c8a50",["Text"]="-----------------------------------\n-- ID: 5610\n-- Item: hellsteak_+1\n-- Food Effect: 240Min, All Races\n-----------------------------------\n-- Health 22\n-- Strength 7\n-- Intelligence -3\n-- Health Regen While Healing 2\n-- hMP +1\n-- Attack % 20 (cap 150)\n-- Ranged ATT % 20 (cap 150)\n-- Dragon Killer 5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 14400, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 22)\n    effect:addMod(xi.mod.STR, 7)\n    effect:addMod(xi.mod.INT, -3)\n    effect:addMod(xi.mod.HPHEAL, 2)\n    effect:addMod(xi.mod.MPHEAL, 1)\n    effect:addMod(xi.mod.FOOD_ATTP, 20)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 150)\n    effect:addMod(xi.mod.FOOD_RATTP, 20)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 150)\n    effect:addMod(xi.mod.DRAGON_KILLER, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/hermes_quencher.lua"]={["Path"]="scripts/items/hermes_quencher.lua",["SHA256"]="0ef797532915c3e9522e46993f3a7f619b97810e393a4c6b60e0ca9bff7b04ff",["Text"]="-----------------------------------\n-- ID: 5255\n-- Item: Hermes Quencher\n-- Item Effect: Flee for 30 seconds\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasStatusEffect(xi.effect.MEDICINE) then\n        return xi.msg.basic.ITEM_NO_USE_MEDICATED\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:delStatusEffect(xi.effect.FLEE)\n    target:addStatusEffect(xi.effect.FLEE, { power = 8750, duration = 30, origin = user })\n    target:messageBasic(xi.msg.basic.GAINS_EFFECT_OF_STATUS, xi.effect.FLEE)\n    target:addStatusEffect(xi.effect.MEDICINE, { duration = 900, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/hi-elixir.lua"]={["Path"]="scripts/items/hi-elixir.lua",["SHA256"]="9a3fea51b3259b5fa6692726fcdaa7e7b291b0892e9ff500fbbd885f1a1c7c64",["Text"]="-----------------------------------\n-- ID: 4144\n-- Item: Hi-Elixir\n-- Item Effect: Instantly restores 50% of HP and MP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    local mHP = target:getMaxHP()\n    local cHP = target:getHP()\n    local mMP = target:getMaxMP()\n    local cMP = target:getMP()\n\n    if mHP == cHP and mMP == cMP then\n        result = 56 -- Does not let player use item if their hp and mp are full\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target)\n    target:addHP((target:getMaxHP() / 100) * 50)\n    target:addMP((target:getMaxMP() / 100) * 50)\n    target:messageBasic(xi.msg.basic.RECOVERS_HP_AND_MP)\nend\n\nreturn itemObject\n"},["scripts/items/hi-elixir_tank.lua"]={["Path"]="scripts/items/hi-elixir_tank.lua",["SHA256"]="43de7cdb8b75d807df2403c0f1598a6491777c7e39fb9f1d1514183e21c79b00",["Text"]="-----------------------------------\n-- ID: 26271\n-- Hi-Elixir Tank\n-- When used, you will obtain one hi-elixir\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.HI_ELIXIR, 1 } })\nend\n\nreturn itemObject\n"},["scripts/items/hi-ether.lua"]={["Path"]="scripts/items/hi-ether.lua",["SHA256"]="233cad216cd31928bdb25f5488f467d0ccb3f8332316e561d42ec8460c020f93",["Text"]="-----------------------------------\n-- ID: 4132\n-- Item: Hi-Ether\n-- Item Effect: Restores 50 MP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getMP() == target:getMaxMP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:messageBasic(xi.msg.basic.RECOVERS_MP, 0, target:addMP(50 * xi.settings.main.ITEM_POWER))\nend\n\nreturn itemObject\n"},["scripts/items/hi-ether_+1.lua"]={["Path"]="scripts/items/hi-ether_+1.lua",["SHA256"]="a6441d7b0beee0c6b61a3101d6cb2b21a612dcf2d704cacf864fa604ad42a387",["Text"]="-----------------------------------\n-- ID: 4133\n-- Item: Hi-Ether +1\n-- Item Effect: Restores 55 MP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getMP() == target:getMaxMP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:messageBasic(xi.msg.basic.RECOVERS_MP, 0, target:addMP(55 * xi.settings.main.ITEM_POWER))\nend\n\nreturn itemObject\n"},["scripts/items/hi-ether_+2.lua"]={["Path"]="scripts/items/hi-ether_+2.lua",["SHA256"]="064a16a390c14ba00ee4281eb37cef8159e9d2b3d47b422f366c93c8359d3ef5",["Text"]="-----------------------------------\n-- ID: 4134\n-- Item: Hi-Ether +2\n-- Item Effect: Restores 60 MP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getMP() == target:getMaxMP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:messageBasic(xi.msg.basic.RECOVERS_MP, 0, target:addMP(60 * xi.settings.main.ITEM_POWER))\nend\n\nreturn itemObject\n"},["scripts/items/hi-ether_+3.lua"]={["Path"]="scripts/items/hi-ether_+3.lua",["SHA256"]="19874d77d