"d7c489bbc6f23b05617aa87b283f792d61a9eb3b9a7cfc528a32f67e7e17bfe9",["Text"]="-----------------------------------\n-- ID: 4117\n-- Item: Hi-Potion +1\n-- Item Effect: Restores 110 HP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getHP() == target:getMaxHP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:messageBasic(xi.msg.basic.RECOVERS_HP, 0, target:addHP(110 * xi.settings.main.ITEM_POWER))\nend\n\nreturn itemObject\n"},["scripts/items/hi-potion_+2.lua"]={["Path"]="scripts/items/hi-potion_+2.lua",["SHA256"]="7e38a900b19507f6620f3fbc3cea88a8172221e421bbb6c1937faec6a4690b70",["Text"]="-----------------------------------\n-- ID: 4118\n-- Item: Hi-Potion +2\n-- Item Effect: Restores 120 HP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getHP() == target:getMaxHP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:messageBasic(xi.msg.basic.RECOVERS_HP, 0, target:addHP(120 * xi.settings.main.ITEM_POWER))\nend\n\nreturn itemObject\n"},["scripts/items/hi-potion_+3.lua"]={["Path"]="scripts/items/hi-potion_+3.lua",["SHA256"]="db5f278c9d93c95f05a34354f8ccfefd03d9ea5744e2e96faafc118fcb18bd19",["Text"]="-----------------------------------\n-- ID: 4119\n-- Item: Hi-Potion +3\n-- Item Effect: Restores 130 HP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getHP() == target:getMaxHP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:messageBasic(xi.msg.basic.RECOVERS_HP, 0, target:addHP(130 * xi.settings.main.ITEM_POWER))\nend\n\nreturn itemObject\n"},["scripts/items/hi-potion_tank.lua"]={["Path"]="scripts/items/hi-potion_tank.lua",["SHA256"]="cda407e3ee7c0632c15b10e640ff5258367e61023f97003d156c98570819ca8e",["Text"]="-----------------------------------\n-- ID: 13688\n-- Hi-Potion Tank\n-- When used, you will obtain one Hi-Potion\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.HI_POTION, 1 } })\nend\n\nreturn itemObject\n"},["scripts/items/hi-reraiser.lua"]={["Path"]="scripts/items/hi-reraiser.lua",["SHA256"]="c9170c68cfafbad7308dc5af08b7010965c7ea4add89994b43516a04b84bfc73",["Text"]="-----------------------------------\n-- ID: 4173\n-- Item: Hi-Reraiser\n-- Item Effect: This potion functions inthe same way as the spell Reraise II.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    local duration = 5400\n    target:delStatusEffect(xi.effect.RERAISE)\n    target:addStatusEffect(xi.effect.RERAISE, { power = 2, duration = duration, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/high_breath_mantle.lua"]={["Path"]="scripts/items/high_breath_mantle.lua",["SHA256"]="cc4b08f2d7e29fd31fa611106fb8cc5073b0eed5cd9cb6874a5cf1c4033fe82c",["Text"]="-----------------------------------\n-- ID: 15487\n-- Item: High Breath Mantle\n-- Item Effect: HP+38 / Enmity+5\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.HIGH_BREATH_MANTLE) ~= nil then\n        target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.HIGH_BREATH_MANTLE)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.HIGH_BREATH_MANTLE) then\n        target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 1800, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.HIGH_BREATH_MANTLE })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.HP, 38)\n    effect:addMod(xi.mod.ENMITY, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/high_healing_harness.lua"]={["Path"]="scripts/items/high_healing_harness.lua",["SHA256"]="a3284b101e24908bdfaf1839153e1262b221c0ec3f7e7209d53566f8b3e7e4f8",["Text"]="-----------------------------------\n-- ID: 14497\n-- Item: High Healing Harness\n-- Item Effect: Restores 90-105 HP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getHP() == target:getMaxHP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local hpHeal = math.randomInt(90, 105)\n    local dif = target:getMaxHP() - target:getHP()\n    if hpHeal > dif then\n        hpHeal = dif\n    end\n\n    target:addHP(hpHeal)\n    target:messageBasic(xi.msg.basic.RECOVERS_HP, 0, hpHeal)\nend\n\nreturn itemObject\n"},["scripts/items/high_mana_cloak.lua"]={["Path"]="scripts/items/high_mana_cloak.lua",["SHA256"]="307f333caee57043d89c515df4d591a03ab0c03314dd0bf5c6d890acac65404a",["Text"]="-----------------------------------\n-- ID: 14492\n-- Item: High Mana Cloak\n-- Item Effect: Restores 50-75 MP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getMP() == target:getMaxMP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local mpHeal = math.randomInt(50, 75)\n    local dif = target:getMaxMP() - target:getMP()\n    if mpHeal > dif then\n        mpHeal = dif\n    end\n\n    target:addMP(mpHeal)\n    target:messageBasic(xi.msg.basic.RECOVERS_MP, 0, mpHeal)\nend\n\nreturn itemObject\n"},["scripts/items/high_mana_wand.lua"]={["Path"]="scripts/items/high_mana_wand.lua",["SHA256"]="91be6bab85dda0cd85f8abbca7e21e275141891a94d80ae92f19f3f632bf3ffe",["Text"]="-----------------------------------\n-- ID: 18403\n-- Item: high_mana_wand\n-- Item Effect: MPHEAL +4\n-- Duration: 30 seconds\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.HIGH_MANA_WAND) ~= nil then\n        target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.HIGH_MANA_WAND)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.HIGH_MANA_WAND) then\n        target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 1800, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.HIGH_MANA_WAND })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.MPHEAL, 4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/hikogami_yukata.lua"]={["Path"]="scripts/items/hikogami_yukata.lua",["SHA256"]="b4ee63b2c8cd597fa9fa749528113322988cf25407a3dda395ec16f22170d75a",["Text"]="-----------------------------------\n-- ID: 11861\n-- hikogami_yukata\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.SUPER_SCOOP, 1 } })\nend\n\nreturn itemObject\n"},["scripts/items/himegami_yukata.lua"]={["Path"]="scripts/items/himegami_yukata.lua",["SHA256"]="9a8cbca6d11545030b7954532f5bd17d6940e810dae6d5be83ffcf024311c946",["Text"]="-----------------------------------\n-- ID: 11862\n-- himegami_yukata\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.SUPER_SCOOP, 1 } })\nend\n\nreturn itemObject\n"},["scripts/items/himesama_rice_ball.lua"]={["Path"]="scripts/items/himesama_rice_ball.lua",["SHA256"]="ed4cd2e5abaa3b8d3a14a104634c26890ad657bfcebffd378343e483ef9f6e51",["Text"]="-----------------------------------\n-- ID: 5928\n-- Item: Himesama Rice Ball\n-- Food Effect: 30 Mins, All Races\n-----------------------------------\n-- HP +25\n-- Dexterity +4\n-- Vitality +4\n-- Character +4\n-- Effect with enhancing equipment (Note: these are latents on gear with the effect)\n-- Attack +60\n-- Defense +40\n-- Triple Attack +1%\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 25)\n    effect:addMod(xi.mod.DEX, 4)\n    effect:addMod(xi.mod.VIT, 4)\n    effect:addMod(xi.mod.CHR, 4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/hobgoblin_pie.lua"]={["Path"]="scripts/items/hobgoblin_pie.lua",["SHA256"]="5c265f41e6afc5365148fccf04936b996ace5462442a83ca6a6f8ae1f39f61cc",["Text"]="-----------------------------------\n-- ID: 4325\n-- Item: hobgoblin_pie\n-- Food Effect: 60Min, All Races\n-----------------------------------\n-- Health 15\n-- Magic 15\n-- Agility 4\n-- Charisma -7\n-- Health Regen While Healing 2\n-- Defense % 12 (cap 60)\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 15)\n    effect:addMod(xi.mod.FOOD_MP, 15)\n    effect:addMod(xi.mod.AGI, 4)\n    effect:addMod(xi.mod.CHR, -7)\n    effect:addMod(xi.mod.HPHEAL, 2)\n    effect:addMod(xi.mod.FOOD_DEFP, 12)\n    effect:addMod(xi.mod.FOOD_DEF_CAP, 60)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/holy_bolt.lua"]={["Path"]="scripts/items/holy_bolt.lua",["SHA256"]="917b7542cf78778e0726c53e57807dc1def31f294fce97b71a9a85471a43db62",["Text"]="-----------------------------------\n-- ID: 18153\n-- Item: Holy Bolt\n-- Additional effect: Light damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat = actor:getStat(xi.mod.MND) - target:getStat(xi.mod.MND)\n    -- Unconfirmed power.\n\n    local pTable =\n    {\n        ignoreEnSpell   = true,\n        basePower       = 40 + utils.clamp(dStat, -3, 8) + utils.clamp(math.floor((dStat - 8) / 2), 0, 8),\n        attackType      = xi.attackType.MAGICAL,\n        magicalElement  = xi.element.LIGHT,\n        canResist       = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/holy_bolt_quiver.lua"]={["Path"]="scripts/items/holy_bolt_quiver.lua",["SHA256"]="9af933a6ccb04c91524e0dab6df47d5921e22f2c9bb31e2ead9725196391296e",["Text"]="-----------------------------------\n-- ID: 5336\n-- Holy Bolt Quiver\n-- When used, you will obtain one stack of Holy Bolts\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.HOLY_BOLT, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/holy_degen.lua"]={["Path"]="scripts/items/holy_degen.lua",["SHA256"]="4dbfd0d09ea65eb7902c43abbec0de5ab9b20474980c0eaa556bd60779f99c59",["Text"]="-----------------------------------\n-- ID: 16523\n-- Item: Holy Degen\n-- Additional effect: light damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat = actor:getStat(xi.mod.MND) - target:getStat(xi.mod.INT)\n    local pTable =\n    {\n        chance         = utils.clamp(dStat * 4 / 9, 0, 24), -- Seems to be a linear scale over 54 dSTAT, 4 / 9 = 0.4444...\n        basePower      = math.randomInt(3, 5),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.LIGHT,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/holy_degen_+1.lua"]={["Path"]="scripts/items/holy_degen_+1.lua",["SHA256"]="cda998ff940cacf45987cf846faa2653e04c483ae78ae55ef708c426c7252bce",["Text"]="-----------------------------------\n-- ID: 16817\n-- Item: Holy Dege