51437e8e49667582a97188b922473f4",["Text"]="-----------------------------------\n-- ID: 17434\n-- Item: Holy Wand +1\n-- Additional effect: light damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat = actor:getStat(xi.mod.MND) - target:getStat(xi.mod.INT)\n    local pTable =\n    {\n        chance         = utils.clamp(dStat * 4 / 9, 0, 24), -- Seems to be a linear scale over 54 dSTAT, 4 / 9 = 0.4444...\n        basePower      = math.randomInt(6, 8),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.LIGHT,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/homemade_omelette.lua"]={["Path"]="scripts/items/homemade_omelette.lua",["SHA256"]="4ae3159d0d9aee13c535645b0ad495d3f5dfbbfd638cc989b4846b37c6cda4f1",["Text"]="-----------------------------------\n-- ID: 5707\n-- Item: homemade_omelette\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- DEF +5\n-- Accuracy +12% (cap 80)\n-- Attack +10% (cap 40)\n-- Ranged Accuracy +12% (cap 80)\n-- Ranged Attack +10% (cap 40)\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEF, 5)\n    effect:addMod(xi.mod.FOOD_ACCP, 12)\n    effect:addMod(xi.mod.FOOD_ACC_CAP, 80)\n    effect:addMod(xi.mod.FOOD_ATTP, 10)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 40)\n    effect:addMod(xi.mod.FOOD_RACCP, 12)\n    effect:addMod(xi.mod.FOOD_RACC_CAP, 80)\n    effect:addMod(xi.mod.FOOD_RATTP, 10)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 40)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/homemade_rice_ball.lua"]={["Path"]="scripts/items/homemade_rice_ball.lua",["SHA256"]="1271a19bbfd5e5f2146f06e2a9d388d0f716e7fa675d8e5c6bfd1c24ee46d41b",["Text"]="-----------------------------------\n-- ID: 5224\n-- Item: homemade_rice_ball\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Dexterity 1\n-- Accuracy +12% (cap 80)\n-- Attack +10% (cap 40)\n-- Ranged Accuracy +12% (cap 80)\n-- Ranged Attack +10% (cap 40)\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 1)\n    effect:addMod(xi.mod.FOOD_ACCP, 12)\n    effect:addMod(xi.mod.FOOD_ACC_CAP, 80)\n    effect:addMod(xi.mod.FOOD_ATTP, 10)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 40)\n    effect:addMod(xi.mod.FOOD_RACCP, 12)\n    effect:addMod(xi.mod.FOOD_RACC_CAP, 80)\n    effect:addMod(xi.mod.FOOD_RATTP, 10)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 40)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/homemade_salisbury_steak.lua"]={["Path"]="scripts/items/homemade_salisbury_steak.lua",["SHA256"]="b1b275dba242fa272dbecadd0793dc0e46069596719e1673c50f4819704b9eab",["Text"]="-----------------------------------\n-- ID: 5705\n-- Item: homemade_salisbury_steak\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- AGI +1\n-- Accuracy +12% (cap 80)\n-- Attack +10% (cap 40)\n-- Ranged Accuracy +12% (cap 80)\n-- Ranged Attack +10% (cap 40)\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\n\n    return xi.effect.FOOD\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, 1)\n    effect:addMod(xi.mod.FOOD_ACCP, 12)\n    effect:addMod(xi.mod.FOOD_ACC_CAP, 80)\n    effect:addMod(xi.mod.FOOD_ATTP, 10)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 40)\n    effect:addMod(xi.mod.FOOD_RACCP, 12)\n    effect:addMod(xi.mod.FOOD_RACC_CAP, 80)\n    effect:addMod(xi.mod.FOOD_RATTP, 10)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 40)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/homemade_steak.lua"]={["Path"]="scripts/items/homemade_steak.lua",["SHA256"]="73eb27c6fed2c3a9686333c86a36fc0f8372050bde2127f03439ae8cef273f22",["Text"]="-----------------------------------\n-- ID: 5226\n-- Item: homemade_steak\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Strength 1\n-- Accuracy +12% (cap 80)\n-- Attack +10% (cap 40)\n-- Ranged Accuracy +12% (cap 80)\n-- Ranged Attack +10% (cap 40)\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, 1)\n    effect:addMod(xi.mod.FOOD_ACCP, 12)\n    effect:addMod(xi.mod.FOOD_ACC_CAP, 80)\n    effect:addMod(xi.mod.FOOD_ATTP, 10)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 40)\n    effect:addMod(xi.mod.FOOD_RACCP, 12)\n    effect:addMod(xi.mod.FOOD_RACC_CAP, 80)\n    effect:addMod(xi.mod.FOOD_RATTP, 10)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 40)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/homing_ring.lua"]={["Path"]="scripts/items/homing_ring.lua",["SHA256"]="33f3c969ed61f73a27217ee7f0f3ae989956b2cedf4c093c81fe482ffe2a7ef1",["Text"]="-----------------------------------\n-- ID: 15541\n-- Teleport Homing Ring\n-- Enchantment: \"Outpost Warp\"\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    local region = target:getCurrentRegion()\n\n    if\n        not xi.conquest.canTeleportToOutpost(target, region) or\n        GetRegionOwner(region) ~= target:getNation()\n    then\n        result = xi.msg.basic.CANT_BE_USED_IN_AREA\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target, user)\n    local region = target:getCurrentRegion()\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.OUTPOST, duration = 4, origin = user, icon = 0, subPower = region })\nend\n\nreturn itemObject\n"},["scripts/items/homura.lua"]={["Path"]="scripts/items/homura.lua",["SHA256"]="cb3273a102fb2ec2edf16ea24d90f9b230df8619bdf14510b6cd333679cb41f0",["Text"]="-----------------------------------\n-- ID: 16973\n-- Item: Homura\n-- Additional effect: fire damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 7, -- TODO: looks like it might scale with INT?\n        basePower      = math.randomInt(6, 8),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.FIRE,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/homura_+1.lua"]={["Path"]="scripts/items/homura_+1.lua",["SHA256"]="0a4d185c9b634f576fb958d30a3d0a71e6289e1de8cb88fcef840afd171a75dc",["Text"]="-----------------------------------\n-- ID: 16986\n-- Item: Homura +1\n-- Additional effect: fire damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 7, -- TODO: looks like it might scale with INT?\n        basePower      = math.randomInt(6, 8),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.FIRE,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/horn_quiver.lua"]={["Path"]="scripts/items/horn_quiver.lua",["SHA256"]="f51209512729a8983711d981706571c41c5f5db52bcbb2e60ef4ae34b3038bb2",["Text"]="-----------------------------------\n-- ID: 4222\n-- Horn Quiver\n-- When used, you will obtain one stack of Horn Arrows\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.HORN_ARROW, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/hume_rice_cake.lua"]={["Path"]="scripts/items/hume_rice_cake.lua",["SHA256"]="b6f0865774429e1a5f5493d12a0969863ad74348502576ef570da68356986c74",["Text"]="-----------------------------------\n-- ID: 5294\n-- Hume Rice Cake\n-- Enchantment: 60Min, Costume - Hume child (female)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if not target:canUseMisc(xi.zoneMisc.COSTUME) then\n        return xi.msg.basic.CANT_BE_USED_IN_AREA\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.COSTUME, { power = 118, duration = 3600, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/humilus_cell.lua"]={["Path"]="scripts/items/humilus_cell.lua",["SHA256"]="151aeaeaaf08efc4b58928e82054335febca81a795e96c12a873834dff2a5218",["Text"]="-----------------------------------\n-- Humilus Cell\n-- ID 5383\n-- Removes HP Down effect\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.salvage.onCellItemCheck(target, xi.effect.DEBILITATION, 0x080)\nend\n\nitemObject.onItemUse = function(target)\n    return xi.salvage.onCellItemUse(target, xi.effect.DEBILITATION, 0x080, 18)\nend\n\nreturn itemObject\n"},["scripts/items/humpty_dumpty_effigy.lua"]={["Path"]="scripts/items/humpty_dumpty_effigy.lua",["SHA256"]="20b571ea53304f8b6b36defa6c699b9e62a0e424df1035d2e65f14d38ee29c45",["Text"]="-----------------------------------\n-- ID: 5683\n-- Item: humpty_dumpty_effigy\n-- Food Effect: 3 hours, All Races\n-----------------------------------\n-- Max HP % 6 (cap 160)\n-- Max MP % 6 (cap 160)\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HPP, 6)\n    effect:addMod(xi.mod.FOOD_HP_CAP, 160)\n    effect:addMod(xi.mod.FOOD_MPP, 6)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 160)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/hydra_doublet.lua"]={["Path"]="scripts/items/hydra_doublet.lua",["SHA256"]="58429dcc94059a6bef00a4a79dd335f19839f0fd455d89a75136621199677cbb",["Text"]="-----------------------------------\n-- ID: 14515\n-- Item: Hydra Doublet\n-- Item Effect: Refresh 3 MP/tick\n-- Duration: 60 Seconds\n-- Stacks with Refresh (spell)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.HYDRA_DOUBLET) then\n        local effect = target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.HYDRA_DOUBLET)\n        if effect then\n            effect:resetStartTime()\n            effect:setIcon(xi.effect.REFRESH)\n        else\n            target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 60, icon = xi.effect.REFRESH, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.HYDRA_DOUBLET, flag = xi.effectFlag.NO_LOSS_MESSAGE })\n        end\n\n        target:messageBasic(xi.msg.basic.GAINS_EFFECT_OF_STATUS, xi.effect.REFRESH)\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.REFRESH, 3)\nend\n\nitemObject.onItemUnequip = function(target, item)\n    target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.HYDRA_DOUBLET)\nend\n\nitemObject.onEffectLose = function(target, effect)\n    target:messageBasic(xi.msg.basic.STATUS_WEARS_OFF, xi.effect.REFRESH)\nend\n\nreturn itemObject\n"},["scripts/items/hydra_harness.lua"]={["Path"]="scripts/items/hydra_harness.lua",["SHA256"]="579d5b1c36718896719b8b1bb9b12ffd7d97da030620304b119e5e874c9d76b9",["Text"]="-----------------------------------\n-- ID: 14516\n-- Item: Hydra Harness\n-- Item Effect: Attack +25, Ranged Attack +25\n-- Duration: 3 Minutes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.HYDRA_HARNESS) then\n        local effect = target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.HYDRA_HARNESS)\n        if effect then\n            effect:resetStartTime()\n            effect:setIcon(xi.effect.ATTACK_BOOST)\n        else\n            target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 180, icon = xi.effect.ATTACK_BOOST, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.HYDRA_HARNESS, flag = xi.effectFlag.NO_LOSS_MESSAGE })\n        end\n\n        target:messageBasic(xi.msg.basic.GAINS_EFFECT_OF_STATUS, xi.effect.ATTACK_BOOST)\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.ATT, 25)\n    effect:addMod(xi.mod.RATT, 25)\nend\n\nitemObject.onItemUnequip = function(target, item)\n    target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.HYDRA_HARNESS)\nend\n\nitemObject.onEffectLose = function(target, effect)\n    target:messageBasic(xi.msg.basic.STATUS_WEARS_OFF, xi.effect.ATTACK_BOOST)\nend\n\nreturn itemObject\n"},["scripts/items/hydra_haubert.lua"]={["Path"]="scripts/items/hydra_haubert.lua",["SHA256"]="0acb4c9dbbe2d8334746893f54b2e9d7588dfd626ee7dacf30572e2f9b25ae75",["Text"]="-----------------------------------\n-- ID: 14517\n-- Item: Hydra Haubert\n-- Item Effect: Refresh 3 MP/tick\n-- Duration: 60 Seconds\n-